#!/usr/bin/env python3
"""Generate the finite injectivity proof for sixteen signed coordinate tags."""

import argparse
from pathlib import Path

HERE = Path(__file__).resolve().parent
NUM = "₀₁₂₃₄₅₆₇"


def source():
    text = """------------------------------------------------------------------------
-- Presentations of groups
--
-- Distinct signed tags recover a sign and one of eight coordinates.
-- Generated by ThreeQubit/build_tags.py.
------------------------------------------------------------------------

{-# OPTIONS --without-K --safe #-}

module Examples.Groups.CCX+HH.ThreeQubit.StabilizerTags where

open import Data.Bool.Base using (Bool ; false ; true)
open import Data.Fin.Base using (Fin)
open import Data.Integer.Base using (+_)
open import Data.Product.Base using (_×_ ; _,_)
open import Relation.Binary.PropositionalEquality using (_≡_ ; refl)
open import Notations
open import Examples.Groups.CCX+HH-TwoLevel.Ring using (D ; ι ; -ᴰ_)
open import Examples.Groups.CCX+HH.ThreeQubit.StabilizerAction using (neg)

tag : Fin 8 → D
"""
    for i in range(8):
        text += f"tag {NUM[i]} = ι (+ {i+1})\n"
    text += """
opaque
  unfolding -ᴰ_

  signed-tag-injective : ∀ a b i j → neg a (tag i) ≡ neg b (tag j) →
    (a ≡ b) × (i ≡ j)
"""
    for a in ("false", "true"):
        for b in ("false", "true"):
            for i in range(8):
                for j in range(8):
                    prefix = f"  signed-tag-injective {a} {b} {NUM[i]} {NUM[j]}"
                    text += prefix + (" _ = refl , refl\n" if a == b and i == j else " ()\n")
    return text


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true", help="compare without writing")
    args = parser.parse_args()
    path = HERE / "StabilizerTags.agda"
    text = source()
    if args.check:
        assert path.read_text(encoding="utf-8") == text, "Generated signed-tag proof differs"
    else:
        path.write_text(text, encoding="utf-8")
    print(("Verified" if args.check else "Generated") + " signed coordinate-tag injectivity.")


if __name__ == "__main__":
    main()
